PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?paternalGrandmother 
WHERE {
  dbr:Teriimaevarua_III dbo:parent ?parent .
  ?parent dbo:parent ?paternalGrandparent .
  ?paternalGrandparent dbo:parent ?paternalGrandmother .
  FILTER (?paternalGrandparent = ?father)
  {
    {
      ?parent dbo:parent ?father .
      ?parent dbo:parent ?mother .
      FILTER (?father != ?mother)
    }
    UNION
    {
      ?parent dbp:father ?father .
      ?parent dbp:mother ?mother .
      FILTER (?father != ?mother)
    }
  }
}
LIMIT 100

